    {
        OrbEventHandler handler = events.get();
        eventBus.register(handler);
        handler.startUp();
        eventBus.register(presentation);
        presentation.start();
        eventBus.register(releaseNotes);
        releaseNotes.start();
        shieldOrb.start();
        eventBus.register(shieldOrb);
        overlayManager.add(shieldOrb);
