import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

@Singleton
public class BetaEquipmentPanel extends Overlay
{
    private static final int[] BUTTONS={InterfaceID.Wornitems.EQUIPMENT,InterfaceID.Wornitems.PRICECHECKER,InterfaceID.Wornitems.DEATHKEEP,InterfaceID.Wornitems.CALL_FOLLOWER};
    private static final int[] ICONS={InterfaceID.Wornitems.EQUIPMENT_ICON,InterfaceID.Wornitems.ROOT_GRAPHIC2,InterfaceID.Wornitems.ROOT_GRAPHIC3,InterfaceID.Wornitems.ROOT_GRAPHIC4};
    private static final String[] LABELS={"Stats","Prices","Death","Follower"};
    @Inject Client client;
    @Inject ClientThread clientThread;
    @Inject InterfaceLayoutConfig config;
    @Inject ItemManager items;
    @Inject MenuButtonSprites sprites;
    @Inject TooltipManager tooltips;
    private final Map<Widget,Geometry> moved=new IdentityHashMap<>();
    private final Set<Widget> hidden=Collections.newSetFromMap(new IdentityHashMap<>());
    private final List<View> views=new ArrayList<>();
    private EquipmentReadout data;
    private volatile boolean dirty=true,running;
    private volatile int generation;
    private int scriptDepth;
    private boolean refreshAfterScript;

    public BetaEquipmentPanel() {
        setPosition(OverlayPosition.DYNAMIC);setLayer(OverlayLayer.ABOVE_WIDGETS);
    }
    public void start() {running=true;generation++;dirty=true;}
    public void stop() {
        running=false;int stopped=++generation;
        clientThread.invoke(()->{if(!running && stopped==generation){restore();data=null;scriptDepth=0;refreshAfterScript=false;}});
    }
    @Subscribe public void onGameTick(GameTick event) {dirty=true;}
    @Subscribe public void onVarbitChanged(net.runelite.api.events.VarbitChanged event) {dirty=true;}
    @Subscribe public void onItemContainerChanged(ItemContainerChanged event) {if(event.getContainerId()==InventoryID.WORN)dirty=true;}
    @Subscribe public void onConfigChanged(ConfigChanged event) {dirty=true;}
    @Subscribe public void onProfileChanged(ProfileChanged event) {
        dirty=true;int requested=++generation;
        clientThread.invokeLater(()->{if(running && requested==generation){restore();data=null;}});
    }
    @Subscribe(priority=3) public void onScriptPreFired(ScriptPreFired event) {

        if(!running)return;
        scriptDepth++;
        if(!moved.isEmpty() || !hidden.isEmpty()){restore();refreshAfterScript=true;}
    }
    @Subscribe(priority=-3) public void onScriptPostFired(ScriptPostFired event) {
        if(!running)return;
        scriptDepth=Math.max(0,scriptDepth-1);
        if(scriptDepth==0 && refreshAfterScript) {
            refreshAfterScript=false;

            onBeforeRender(null);
        }
    }
    @Subscribe public void onGameStateChanged(GameStateChanged event) {
        if(event.getGameState()!=GameState.LOGGED_IN){restore();data=null;dirty=true;}
    }
    @Subscribe(priority=-3) public void onBeforeRender(BeforeRender event) {
        if(event!=null){scriptDepth=0;refreshAfterScript=false;}
        if(!running || !config.betaEquipmentPanel() || client.getGameState()!=GameState.LOGGED_IN) {restore();data=null;dirty=true;return;}
        views.clear();
        Widget tab=client.getWidget(InterfaceID.Wornitems.UNIVERSE);
        if(!visible(tab)) {restore();return;}
        if(dirty || data==null) {data=EquipmentReadout.capture(client,items);dirty=false;}
        Set<Widget> retained=Collections.newSetFromMap(new IdentityHashMap<>());
        if(visible(tab) && tab.getWidth()>=184 && tab.getHeight()>=261) {
            Rectangle bounds=tab.getBounds();Rectangle footer=new Rectangle(bounds.x+3,bounds.y+198,184,EquipmentReadoutRenderer.HEIGHT);
            boolean[] available=new boolean[4];
            for(int i=0;i<BUTTONS.length;i++) {
                Widget button=client.getWidget(BUTTONS[i]),icon=client.getWidget(ICONS[i]);
                if(!visible(button)) continue;
                available[i]=true;
                place(button,7+i*21,243,18,18);retained.add(button);
                hide(icon,retained);

                Widget[] frame=button.getDynamicChildren();
                if(frame!=null) for(Widget piece:frame) hide(piece,retained);
            }
            views.add(new View(tab,footer,data,available));
        }
        restoreUnused(retained);
    }
    private static boolean visible(Widget widget) {return widget!=null && !widget.isHidden();}
    private void hide(Widget widget,Set<Widget> retained) {
        if(widget==null)return;retained.add(widget);
        if(!widget.isSelfHidden()) {hidden.add(widget);widget.setHidden(true);}
    }
    private void place(Widget widget,int x,int y,int width,int height) {
        Geometry current=Geometry.read(widget),saved=moved.get(widget);
        if(saved==null || !current.equals(saved.applied)) {saved=current;moved.put(widget,saved);}
        Geometry desired=new Geometry(x,y,width,height,0,0,0,0);
        if(!desired.equals(current)){desired.apply(widget);widget.revalidate();}
        saved.applied=desired;
    }
    private boolean current(Widget widget) {
        if(widget.getIndex()<0)return client.getWidget(widget.getId())==widget;
        Widget parent=client.getWidget(widget.getId());return parent!=null && parent.getChild(widget.getIndex())==widget;
    }
    private void restoreUnused(Set<Widget> retained) {
        moved.entrySet().removeIf(entry->{if(retained.contains(entry.getKey()))return false;
            Widget widget=entry.getKey();if(current(widget) && Geometry.read(widget).equals(entry.getValue().applied)){entry.getValue().apply(widget);widget.revalidate();}return true;});
        hidden.removeIf(widget->{if(retained.contains(widget))return false;if(current(widget) && widget.isSelfHidden())widget.setHidden(false);return true;});
    }
    private void restore() {views.clear();restoreUnused(Collections.emptySet());}
    @Override public Dimension render(Graphics2D graphics) {
        if(!running || !config.betaEquipmentPanel() || data==null)return null;
        net.runelite.api.Point mouse=client.getMouseCanvasPosition();
        for(View view:views) {
            if(!visible(view.root) || !current(view.root))continue;
            boolean reducedTooltips=config.betaEquipmentReducedTooltips();
            List<EquipmentReadoutRenderer.Hint> hints=EquipmentReadoutRenderer.draw(graphics,view.bounds,view.data,reducedTooltips);
            Rectangle help=helpBounds(view.root.getBounds());
            Graphics2D helpGraphics=(Graphics2D)graphics.create();
            try {
                helpGraphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);
                helpGraphics.setColor(new Color(39,38,32));helpGraphics.fillOval(help.x,help.y,16,16);
                helpGraphics.setColor(new Color(165,150,112));helpGraphics.drawOval(help.x,help.y,15,15);
                helpGraphics.setFont(new Font("Arial",Font.BOLD,12));helpGraphics.setColor(new Color(255,224,154));
                helpGraphics.drawString("?",help.x+4,help.y+12);
            } finally {helpGraphics.dispose();}
            hints.add(new EquipmentReadoutRenderer.Hint(help,view.data.details));
            for(int i=0;i<4;i++) if(view.available[i]) {
                Rectangle r=new Rectangle(view.bounds.x+4+i*21,view.bounds.y+45,18,18);
                Graphics2D g=(Graphics2D)graphics.create();try {
                    g.setColor(new Color(55,53,44));g.fillRect(r.x,r.y,r.width,r.height);
                    g.setColor(new Color(126,113,83));g.drawRect(r.x,r.y,17,17);
                    BufferedImage icon=sprites.get(client.getWidget(ICONS[i]));
                    if(icon!=null)g.drawImage(icon,r.x+2,r.y+2,14,14,null);
                    else {g.setFont(new Font("Arial",Font.BOLD,9));g.setColor(Color.WHITE);g.drawString(LABELS[i].substring(0,1),r.x+5,r.y+12);}
                } finally {g.dispose();}
                hints.add(new EquipmentReadoutRenderer.Hint(r,LABELS[i]+(reducedTooltips?"":" - native equipment control")));
            }
            if(tooltips!=null && mouse!=null && !client.isMenuOpen())for(var hint:hints)if(hint.bounds.contains(mouse.getX(),mouse.getY()))tooltips.add(new Tooltip(hint.text));
        }
        return null;
    }
    static Rectangle helpBounds(Rectangle panel) {return new Rectangle(panel.x+6,panel.y+6,16,16);}
    private static final class View {
        final Widget root;final Rectangle bounds;final EquipmentReadout data;final boolean[] available;
        View(Widget root,Rectangle bounds,EquipmentReadout data,boolean[] available){this.root=root;this.bounds=bounds;this.data=data;this.available=available;}
    }
    private static final class Geometry {
        final int[] values;Geometry applied;
        Geometry(int... values){this.values=values;}
        static Geometry read(Widget w){return new Geometry(w.getOriginalX(),w.getOriginalY(),w.getOriginalWidth(),w.getOriginalHeight(),w.getXPositionMode(),w.getYPositionMode(),w.getWidthMode(),w.getHeightMode());}
        void apply(Widget w){w.setPos(values[0],values[1],values[4],values[5]);w.setSize(values[2],values[3],values[6],values[7]);}
        @Override public boolean equals(Object o){return o instanceof Geometry && Arrays.equals(values,((Geometry)o).values);}
        @Override public int hashCode(){return Arrays.hashCode(values);}
    }
}

package com.interfacelayout.layout.equipment;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemComposition;
import net.runelite.api.ParamID;
import net.runelite.api.StructComposition;
import net.runelite.api.VarPlayer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.util.Text;

final class EquipmentDetails {

    private static final int SET_DESCRIPTIONS = 3047;
    private EquipmentDetails() {}

    static String capture(Client client, ItemManager items) {
        ItemContainer worn = client.getItemContainer(InventoryID.WORN);
        if (worn == null) return "Equipment details unavailable";
        Set<String> names = new LinkedHashSet<>();
        Item[] equipped = worn.getItems();
        for (Item item : equipped) if (item != null && item.getId() >= 0 && item.getQuantity() > 0) {
            ItemComposition definition = items.getItemComposition(item.getId());
            if (definition != null && definition.getName() != null)
                names.add(definition.getName().toLowerCase(Locale.ROOT));
        }
        Item weapon = equipped.length > 3 ? equipped[3] : null;
        int base = 4;
        String weaponName = "Unarmed";
        if (weapon != null && weapon.getId() >= 0 && weapon.getQuantity() > 0) {
            ItemStats stats = items.getItemStats(weapon.getId());
            base = stats == null || stats.getEquipment() == null ? 0 : stats.getEquipment().getAspeed();
            ItemComposition definition = items.getItemComposition(weapon.getId());
            weaponName = definition == null ? "Weapon" : definition.getName();
        }
        String style = style(client);
        int selectedStyle = client.getVarpValue(VarPlayer.ATTACK_STYLE);
        int adjusted = adjustedSpeed(base, weaponName, style, selectedStyle,
            client.getVarbitValue(VarbitID.SPELLBOOK));
        List<String> lines = new ArrayList<>();
        lines.add("<col=ffffff>Weapon speed</col>");
        lines.add("Base: " + interval(base));
        lines.add("Adjusted (style/gear): " + interval(adjusted));

        List<String> effects = new ArrayList<>();
        int set = client.getVarbitValue(VarbitID.WORN_ITEMS_SET_TEXT);
        EnumComposition descriptions = client.getEnum(SET_DESCRIPTIONS);
        if (set > 0 && descriptions != null) {
            String text = descriptions.getStringValue(set);
            if (text != null && !text.isBlank() && !"null".equals(text)) effects.add(plain(text));
        }

        active(client,effects,VarbitID.WORN_ITEMS_CRYSTAL_ARMOUR,"Crystal armour: boosts accuracy and damage with crystal bows; the bonus depends on the pieces worn.");
        active(client,effects,VarbitID.WORN_ITEMS_INQUISITORS_ARMOUR,"Inquisitor's armour: boosts crush accuracy and damage; the bonus depends on the pieces worn.");
        active(client,effects,VarbitID.WORN_ITEMS_VIRTUSSET,"Virtus robes: additional damage when casting Ancient Magicks.");
        active(client,effects,VarbitID.WORN_ITEMS_SWAMPBARK_SET,"Swampbark: longer Bind, Snare and Entangle duration per qualifying piece.");
        active(client,effects,VarbitID.WORN_ITEMS_BLOODBARK_SET,"Bloodbark: increased healing from Blood spells per piece.");
        active(client,effects,VarbitID.WORN_ITEMS_PADOS_ROBES_SET,"Zealot's robes: chance to save prayer-training supplies per piece.");
        active(client,effects,VarbitID.WORN_ITEMS_GRACEFUL_SET,"Graceful: faster run-energy restoration; the bonus depends on pieces worn.");
        active(client,effects,VarbitID.WORN_ITEMS_RC_OUTFIT,"Raiments of the Eye: extra runes from Runecraft.");
        active(client,effects,VarbitID.WORN_ITEMS_SMITHING_UNIFORM,"Smiths' uniform: chance to smith faster.");
        active(client,effects,VarbitID.WORN_ITEMS_SPIRIT_ANGLER,"Spirit angler: Fishing experience bonus; the complete outfit works as a rope at Tempoross.");
        active(client,effects,VarbitID.WORN_ITEMS_TRAWLER_BONUS,"Angler: Fishing experience bonus.");
        active(client,effects,VarbitID.WORN_ITEMS_LUMBERJACK_FULL_OUTFIT,"Lumberjack: Woodcutting experience bonus.");
        active(client,effects,VarbitID.WORN_ITEMS_PROSPECTOR_SET,"Prospector: Mining experience bonus.");
        active(client,effects,VarbitID.WORN_ITEMS_FARMING_SET,"Farmer: Farming experience bonus.");
        active(client,effects,VarbitID.WORN_ITEMS_PYROMANCER_SET,"Pyromancer: Firemaking experience bonus.");
        active(client,effects,VarbitID.WORN_ITEMS_ROGUE_SET,"Rogue: chance of double pickpocket loot.");
        active(client,effects,VarbitID.WORN_ITEMS_CARPENTER_SET,"Carpenter: Construction experience bonus.");
        active(client,effects,VarbitID.WORN_ITEMS_DIZANAS_QUIVER_CHARGED,"Dizana's Sunfire: extra Ranged attack and strength when using arrows or bolts.");
        active(client,effects,VarbitID.WORN_ITEMS_ZARYTEXBOW,"Zaryte crossbow: stronger enchanted-bolt effects.");
        active(client,effects,VarbitID.WORN_ITEMS_TUMEKENS_SHADOW,"Tumeken's shadow: multiplies Magic attack and damage bonuses from worn gear when using its built-in spell.");
        if (has(names,"blood moon helm") && has(names,"blood moon chestplate")
            && has(names,"blood moon tassets") && has(names,"dual macuahuitl"))
            effects.add("Blood moon's speed effect is conditional; a proc can shorten the next attack interval.");
        lines.add("<col=ffffff>Set & equipment effects</col>");
        if (effects.isEmpty()) lines.add(set > 0 ? "Set description unavailable" : "No set effect reported by the game");
        else lines.addAll(effects);
        List<String> targets = targetEffects(names);
        active(client,targets,VarbitID.WORN_ITEMS_TWISTED_BOW,"Twisted bow: accuracy and damage scale with the target's magical strength.");
        active(client,targets,VarbitID.WORN_ITEMS_SCYTHE_OF_VITUR,"Scythe: additional hits against large targets or multiple nearby targets.");
        active(client,targets,VarbitID.WORN_ITEMS_KERISPARTISANSUN,"Sun partisan in Tombs of Amascut: extra accuracy against targets below 25% health; kills can trade Prayer for healing.");
        active(client,targets,VarbitID.WORN_ITEMS_SHAYZIEN_SET,"Shayzien armour: protection against lizardman shaman acid attacks.");
        lines.add("<col=ffffff>Target-specific conditions</col>");
        lines.addAll(targets.isEmpty() ? java.util.Collections.singletonList("No supported target bonus identified") : targets);
        return wrap(lines);
    }

    static int adjustedSpeed(int base, String weapon, String style, int selectedStyle, int spellbook) {
        if (base <= 0) return 0;
        String name = weapon == null ? "" : weapon.toLowerCase(Locale.ROOT);
        if (name.startsWith("obligator") && selectedStyle >= 2) return 3;
        if ("Rapid".equalsIgnoreCase(style)) return Math.max(1,base-1);
        if ("Casting".equalsIgnoreCase(style) || "Defensive casting".equalsIgnoreCase(style)) {
            if (name.equals("harmonised nightmare staff") && spellbook == 0) return 4;
            if (name.equals("twinflame staff")) return 6;
            return 5;
        }

        return style == null ? 0 : base;
    }

    private static String style(Client client) {
        int category = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
        int selection = client.getVarpValue(VarPlayer.ATTACK_STYLE);
        if (selection < 0) return null;

        if (category == 22) return selection == 4 ? "Casting" : "Melee";
        if (category == 30) return "Melee";
        EnumComposition categories = client.getEnum(EnumID.WEAPON_STYLES);
        if (categories == null) return null;
        int enumId = categories.getIntValue(category);
        if (enumId < 0) return null;
        EnumComposition styles = client.getEnum(enumId);
        if (styles == null || styles.getIntVals() == null || selection >= styles.getIntVals().length) return null;
        StructComposition value = client.getStructComposition(styles.getIntVals()[selection]);
        if (value == null) return null;
        String name = value.getStringValue(ParamID.ATTACK_STYLE_NAME);

        return selection == 4 ? "Casting" : name;
    }

    static List<String> targetEffects(Set<String> names) {
        List<String> result = new ArrayList<>();
        if (has(names,"slayer helmet") || has(names,"black mask"))
            result.add("Slayer headgear: bonus against assigned Slayer targets; imbued versions also support Ranged and Magic.");
        if (has(names,"salve amulet"))
            result.add("Salve amulet: bonus against undead; (e) improves it and (i) extends it to Ranged and Magic. Does not stack with Slayer headgear.");
        if (has(names,"dragon hunter")) result.add("Dragon hunter weapon: increased accuracy and damage against draconic targets.");
        if (has(names,"arclight") || has(names,"emberlight") || has(names,"darklight") || has(names,"scorching bow"))
            result.add("Demonbane weapon: increased effectiveness against demons; resistance varies by target.");
        if (has(names,"silverlight")) result.add("Silverlight: increased effectiveness against demons.");
        if (has(names,"keris")) result.add("Keris: extra damage and a chance of a stronger hit against kalphites and scabarites.");
        if (has(names,"leaf-bladed")) result.add("Leaf-bladed weapon: can damage turoths and kurasks; the battleaxe also gains bonus damage.");
        if (has(names,"crystal halberd")) result.add("Crystal halberd: its special attack gains a second hit against large targets.");
        if (has(names,"craw's bow") || has(names,"webweaver bow") || has(names,"viggora's chainmace")
            || has(names,"ursine chainmace") || has(names,"thammaron's sceptre") || has(names,"accursed sceptre"))
            result.add("Wilderness weapon: charged variants gain a bonus against NPCs in the Wilderness.");
        if (has(names,"bone mace") || has(names,"bone shortbow") || has(names,"bone staff"))
            result.add("Rat bone weapon: bonus damage against rats; attacks against Scurrius' giant rats can be one tick apart.");
        return result;
    }

    private static boolean has(Set<String> names, String part) {
        for (String name : names) if (name.contains(part)) return true;
        return false;
    }
    private static void active(Client client,List<String> lines,int bit,String text) {
        if (client.getVarbitValue(bit) > 0) lines.add(text);
    }
    private static String interval(int ticks) {
        return ticks <= 0 ? "Unavailable" : String.format(Locale.ROOT,"%d ticks (%.1f s)",ticks,ticks*0.6);
    }
    private static String plain(String text) {
        return Text.removeTags(text.replace("<br>"," ")).replaceAll("\\s+"," ").trim();
    }
    static String wrap(List<String> paragraphs) {
        List<String> lines = new ArrayList<>();
        for (String paragraph : paragraphs) {
            if (paragraph.startsWith("<col=ffffff>") && paragraph.endsWith("</col>")
                && !paragraph.contains("<br>") && plain(paragraph).length() < 40) {
                lines.add(paragraph); continue;
            }
            StringBuilder line = new StringBuilder();
            for (String word : plain(paragraph).split(" ")) {
                if (line.length() > 0 && line.length()+word.length()+1 > 55) {
                    lines.add(line.toString());line.setLength(0);
                }
                if (line.length() > 0) line.append(' ');
                line.append(word);
            }
            if (line.length()>0) lines.add(line.toString());
        }
        return String.join("<br>",lines);
    }
}

package com.interfacelayout.layout.equipment;

import java.util.Locale;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

public final class EquipmentReadout
{
    public final double[] bonuses;
    public final boolean complete;
    public final String spellbook;
    public final int weight;
    public final String details;
    EquipmentReadout(double[] bonuses,boolean complete,String spellbook,int weight) {
        this(bonuses,complete,spellbook,weight,"Equipment details unavailable");
    }
    EquipmentReadout(double[] bonuses,boolean complete,String spellbook,int weight,String details) {
        this.bonuses=bonuses.clone();this.complete=complete;this.spellbook=spellbook;this.weight=weight;
        this.details=details;
    }
    static EquipmentReadout capture(Client client,ItemManager manager) {
        double[] totals=new double[14];boolean complete=true;
        ItemContainer container=client.getItemContainer(InventoryID.WORN);
        if(container==null) complete=false;
        else for(Item item:container.getItems()) if(item!=null && item.getId()>=0 && item.getQuantity()>0) {
            ItemStats stats=manager.getItemStats(item.getId());
            if(stats==null || stats.getEquipment()==null) {complete=false;continue;}
            add(totals,stats.getEquipment());
        }
        return new EquipmentReadout(totals,complete,book(client.getVarbitValue(VarbitID.SPELLBOOK)),client.getWeight(),
            EquipmentDetails.capture(client,manager));
    }
    static void add(double[] values,ItemEquipmentStats stats) {
        double[] item={stats.getAstab(),stats.getAslash(),stats.getAcrush(),stats.getAmagic(),stats.getArange(),
            stats.getDstab(),stats.getDslash(),stats.getDcrush(),stats.getDmagic(),stats.getDrange(),
            stats.getStr(),stats.getRstr(),stats.getMdmg(),stats.getPrayer()};
        for(int i=0;i<values.length;i++) values[i]+=item[i];
    }
    static String book(int value) {
        switch(value) {case 0:return "Standard";case 1:return "Ancient";case 2:return "Lunar";case 3:return "Arceuus";default:return "Unknown";}
    }
    public String value(int index) {
        if(!complete)return "?";
        double value=bonuses[index];String number=Math.abs(value-Math.rint(value))<0.001
            ?String.format(Locale.ROOT,"%.0f",value):String.format(Locale.ROOT,"%.1f",value);
        return (value>0?"+":"")+number+(index==12?"%":"");
    }
}

package com.interfacelayout.layout.equipment;

import java.awt.*;
import java.util.ArrayList;
import java.util.List;

public final class EquipmentReadoutRenderer
{
    public static final int HEIGHT=63;
    public static final class Hint {
        final Rectangle bounds;final String text;
        Hint(Rectangle bounds,String text) {this.bounds=bounds;this.text=text;}
    }
    public static List<Hint> draw(Graphics2D graphics,Rectangle bounds,EquipmentReadout data,boolean reducedTooltips) {
        List<Hint> hints=new ArrayList<>();Graphics2D g=(Graphics2D)graphics.create();
        try {
            g.clip(bounds);g.setColor(new Color(25,23,19,235));g.fillRoundRect(bounds.x,bounds.y,bounds.width,bounds.height,5,5);
            g.setColor(new Color(104,90,65));g.drawRoundRect(bounds.x,bounds.y,bounds.width-1,bounds.height-1,5,5);
            g.setFont(new Font("Arial",Font.PLAIN,9));
            String[] labels={"Stab","Slash","Crush","Magic","Range"};
            int step=10;
            int labelWidth=12,cell=(bounds.width-labelWidth-4)/5;
            g.setColor(new Color(165,155,135));g.drawString("A",bounds.x+3,bounds.y+2*step);g.drawString("D",bounds.x+3,bounds.y+3*step);
            for(int i=0;i<5;i++) {
                int x=bounds.x+labelWidth+i*cell;
                g.setColor(new Color(210,185,125));center(g,labels[i],x,bounds.y+step,cell);
                g.setColor(new Color(255,229,115));center(g,data.value(i),x,bounds.y+2*step,cell);
                g.setColor(new Color(208,212,220));center(g,data.value(i+5),x,bounds.y+3*step,cell);
                hints.add(new Hint(new Rectangle(x,bounds.y,cell,3*step+2),labels[i]+" attack: "+data.value(i)+"<br>"+labels[i]+" defence: "+data.value(i+5)+(reducedTooltips?"":"<br>"+source(data))));
            }
            String[] other={"S "+data.value(10),"R "+data.value(11),"M "+data.value(12),"P "+data.value(13),data.weight+"kg"};
            String[] names={"Melee strength","Ranged strength","Magic damage","Prayer bonus","Total carried weight, including inventory (client value)"};
            for(int i=0;i<5;i++) {
                int x=bounds.x+i*bounds.width/5;g.setColor(new Color(230,205,145));center(g,other[i],x,bounds.y+4*step+1,bounds.width/5);
                String name=i==4 && reducedTooltips?"Carried weight":names[i];
                hints.add(new Hint(new Rectangle(x,bounds.y+3*step+2,bounds.width/5,step+1),name+": "+other[i].replaceFirst("^[SRMP] ","")+(i==4 || reducedTooltips?"":"<br>"+source(data))));
            }
            int bookX=bounds.x+88,bookWidth=bounds.width-92;
            g.setColor(new Color(160,203,213));center(g,data.spellbook,bookX,bounds.y+57,bookWidth);
            hints.add(new Hint(new Rectangle(bookX,bounds.y+4*step+4,bookWidth,18),"Current spellbook: "+data.spellbook));
        } finally {g.dispose();}
        return hints;
    }
    private static String source(EquipmentReadout data) {
        return data.complete?
            "Base item bonuses. Conditional weapon, set and target effects may differ; open equipment stats for the game's effective values.":
            "Equipment data is incomplete. Unknown totals are not shown as zero.";
    }
    private static void center(Graphics2D g,String text,int x,int baseline,int width) {
        g.drawString(text,x+Math.max(0,(width-g.getFontMetrics().stringWidth(text))/2),baseline);
    }
}

