@Singleton
public class MenuButtonOverlay extends Overlay
{
    @Inject private Client client;
    @Inject private InterfaceLayoutConfig config;
    @Inject private WidgetStateStore states;
    @Inject private MenuButtonSprites sprites;
    @Inject private EventBus eventBus;
    private final Map<Integer, Button> prepared = new HashMap<>();
    private final List<Button> placed = new ArrayList<>();
    private boolean active;
    private boolean modern;
    private int root;

    public MenuButtonOverlay()
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(Overlay.PRIORITY_LOW);
    }

    public void clear() { active = false; prepared.clear(); placed.clear(); }
    public void stop() { clear(); sprites.clear(); }
    public boolean active() { return active; }
    public int scaled(int size)
    {
        int percent = Math.max(25, Math.min(200, config.menuGroupSize()));
        return Math.max(1, (int) Math.round(size * percent / 100.0));
    }

    public void prepare(int[][] registry, int[] rows, boolean modern)
    {
        clear();
        if (!config.menuOverlayButtons()) return;
        this.modern = modern;
        root = client.getTopLevelInterfaceId();
        for (int index = 0; index < registry.length; index++)
        {
            Widget stone = client.getWidget(registry[index][0]), icon = client.getWidget(registry[index][1]);
            if (stone == null || icon == null || icon.isHidden()) continue;
            String[] actions = stone.getActions();

            if (stone.getOnOpListener() == null || actions == null || actions.length == 0
                || actions[0] == null || actions[0].isBlank()) { clear(); return; }
            if (stone.getWidth() <= 0 || stone.getHeight() <= 0 || sprites.get(icon) == null)
            { clear(); return; }
            prepared.put(index, new Button(index, stone, icon, client.getWidget(rows[index / 7])));
        }
        active = !prepared.isEmpty();
    }

    public void hideRow(int component) { states.hide(client.getWidget(component), true); }

    public void dimensions(int index, int width, int height, Point stoneOffset, Point iconOffset)
    {
        Button button = prepared.get(index);
        if (button == null) return;
        button.width = width; button.height = height;
        button.stoneOffset = new Point(stoneOffset); button.iconOffset = new Point(iconOffset);
    }

    public void place(int index, Rectangle bounds, boolean covered)
    {
        Button button = prepared.get(index);
        if (button == null) return;
        states.hide(button.stone, true); states.hide(button.icon, true);
        if (covered) return;
        button.bounds = new Rectangle(bounds);
        placed.add(button);
    }

    private boolean current()
    {
        return active && config.menuOverlayButtons() && client.getGameState() == GameState.LOGGED_IN
            && client.getTopLevelInterfaceId() == root;
    }

    private boolean current(Button button)
    {
        return current() && client.getWidget(button.stone.getId()) == button.stone
            && client.getWidget(button.icon.getId()) == button.icon
            && !states.isHiddenByGame(button.icon);
    }

    @Override public Dimension render(Graphics2D graphics)
    {
        if (!current()) return null;
        boolean keepNativeIcons = config.menuKeepNativeIcons();
        net.runelite.api.Point mouse = client.getMouseCanvasPosition();
        for (Button button : placed)
        {
            if (!current(button)) continue;

            if (mouse != null && button.bounds.contains(mouse.getX(), mouse.getY()) && foreignInterfaceMenu()) continue;
            Graphics2D draw = (Graphics2D) graphics.create();
            try
            {
                draw.clip(button.bounds);
                draw.translate(button.bounds.x, button.bounds.y);
                draw.scale((double) button.bounds.width / button.width, (double) button.bounds.height / button.height);
                draw.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
                if (button.row != null && button.rowVisible && !(modern && button.index == 10 && !config.restoreLogoutTab()))
                {
                    Rectangle area = modern ? new Rectangle(0, 0, button.width, button.height)
                        : new Rectangle(button.rowBounds.x - button.nativeBounds.x,
                            button.rowBounds.y - button.nativeBounds.y, button.rowBounds.width, button.rowBounds.height);
                    paint(draw, button.row, area, modern || button.row.getSpriteTiling());
                }
                if (!states.isHiddenByGame(button.stone))
                    paint(draw, button.stone, new Rectangle(button.stoneOffset.x, button.stoneOffset.y,
                        button.stone.getWidth(), button.stone.getHeight()), button.stone.getSpriteTiling());
                if (!keepNativeIcons)
                    paint(draw, button.icon, new Rectangle(button.iconOffset.x, button.iconOffset.y,
                        button.icon.getWidth(), button.icon.getHeight()), button.icon.getSpriteTiling());
            }
            finally { draw.dispose(); }
            if (keepNativeIcons)
            {

                Graphics2D iconDraw = (Graphics2D) graphics.create();
                try
                {
                    iconDraw.clip(button.bounds);
                    iconDraw.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
                    paint(iconDraw, button.icon, centredIconBounds(button), button.icon.getSpriteTiling());
                }
                finally { iconDraw.dispose(); }
            }
            if (!client.isMenuOpen() && mouse != null && button.bounds.contains(mouse.getX(), mouse.getY()))
            {
                graphics.setColor(new Color(255, 210, 100, 140));
                graphics.drawRect(button.bounds.x, button.bounds.y, button.bounds.width - 1, button.bounds.height - 1);
            }
        }
        return null;
    }

    private Rectangle centredIconBounds(Button button)
    {
        double scale = Math.min(1.0, Math.min((double) button.bounds.width / button.width,
            (double) button.bounds.height / button.height));
        int width = Math.min(button.bounds.width, Math.max(1, (int) Math.round(button.icon.getWidth() * scale)));
        int height = Math.min(button.bounds.height, Math.max(1, (int) Math.round(button.icon.getHeight() * scale)));
        return new Rectangle(button.bounds.x + (button.bounds.width - width) / 2,
            button.bounds.y + (button.bounds.height - height) / 2, width, height);
    }

    private void paint(Graphics2D graphics, Widget widget, Rectangle area, boolean tiled)
    {
        BufferedImage image = sprites.get(widget);
        if (image == null || area.width <= 0 || area.height <= 0) return;
        Graphics2D draw = (Graphics2D) graphics.create();
        try
        {
            draw.setComposite(AlphaComposite.SrcOver.derive((256 - Math.max(0, Math.min(255, widget.getOpacity()))) / 256f));
            if (tiled)
            {
                draw.setPaint(new TexturePaint(image, new Rectangle(area.x, area.y, image.getWidth(), image.getHeight())));
                draw.fill(area);
            }
            else
            {
                int x1 = widget.isFlippedHorizontally() ? image.getWidth() : 0, x2 = image.getWidth() - x1;
                int y1 = widget.isFlippedVertically() ? image.getHeight() : 0, y2 = image.getHeight() - y1;
                draw.drawImage(image, area.x, area.y, area.x + area.width, area.y + area.height, x1, y1, x2, y2, null);
            }
        }
        finally { draw.dispose(); }
    }

    @Subscribe(priority = -20)
    public void onPostMenuSort(PostMenuSort event)
    {
        if (!current() || client.isMenuOpen() || foreignInterfaceMenu()) return;
        net.runelite.api.Point mouse = client.getMouseCanvasPosition();
        if (mouse == null) return;
        for (Button button : placed)
        {
            if (!button.bounds.contains(mouse.getX(), mouse.getY()) || !current(button)) continue;
            String[] actions = button.stone.getActions();
            if (actions == null || button.stone.getOnOpListener() == null) return;
            Menu menu = client.getMenu();
            if (menu == null) return;

            for (MenuEntry entry : menu.getMenuEntries())
                if (entry.getType() != MenuAction.CANCEL) menu.removeMenuEntry(entry);
            for (int slot = Math.min(10, actions.length) - 1; slot >= 0; slot--)
            {
                if (actions[slot] == null || actions[slot].isBlank()) continue;
                MenuEntry entry = menu.createMenuEntry(-1).setOption(actions[slot]).setTarget("")
                    .setType(slot < 5 ? MenuAction.CC_OP : MenuAction.CC_OP_LOW_PRIORITY)
                    .setIdentifier(slot + 1).setParam0(-1).setParam1(button.stone.getId());

                eventBus.post(new MenuEntryAdded(entry));
            }
            return;
        }
    }

    private boolean foreignInterfaceMenu()
    {
        Menu menu = client.getMenu();
        if (menu == null) return false;
        for (MenuEntry entry : menu.getMenuEntries())
        {
            if (entry.getType() == MenuAction.RUNELITE_OVERLAY || entry.getType() == MenuAction.RUNELITE_OVERLAY_CONFIG) return true;
            Widget widget = entry.getWidget();
            if (widget == null) continue;
            boolean own = false;
            for (Button button : placed) own |= widget == button.stone || widget == button.icon;
            if (!own) return true;
        }
        return false;
    }

    private static final class Button
    {
        final int index;
        final Widget stone, icon, row;
        final Rectangle nativeBounds, rowBounds;
        final boolean rowVisible;
        Rectangle bounds;
        int width, height;
        Point stoneOffset, iconOffset;
        Button(int index, Widget stone, Widget icon, Widget row)
        {
            this.index = index; this.stone = stone; this.icon = icon; this.row = row;
            nativeBounds = WidgetGeometry.bounds(stone);
            rowBounds = WidgetGeometry.bounds(row);
            rowVisible = row != null && !row.isHidden();
        }
    }
}

package com.interfacelayout.layout.menu;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.SpritePixels;
import net.runelite.api.widgets.Widget;

@Singleton
public class MenuButtonSprites
{
    @Inject private Client client;
    private final Map<Integer, BufferedImage> originals = boundedMap();
    private final Map<Integer, BufferedImage> paddedOriginals = boundedMap();
    private final Map<Integer, OverrideImage> replacements = boundedMap();
    private final Map<Integer, OverrideImage> paddedReplacements = boundedMap();

    public BufferedImage get(Widget widget)
    {
        if (widget == null) return null;
        int spriteId = widget.getSpriteId();
        SpritePixels replacement = client.getWidgetSpriteOverrides().get(widget.getId());
        if (replacement == null) replacement = client.getSpriteOverrides().get(spriteId);
        if (replacement != null)
        {
            OverrideImage cached = replacements.get(widget.getId());

            if (cached == null || cached.source != replacement)
            {
                cached = new OverrideImage(replacement, replacement.toBufferedImage());
                replacements.put(widget.getId(), cached);
            }
            return cached.image;
        }
        replacements.remove(widget.getId());
        if (spriteId < 0) return null;
        BufferedImage image = originals.get(spriteId);
        if (image == null)
        {
            SpritePixels[] sprites = client.getSprites(client.getIndexSprites(), spriteId, 0);
            if (sprites != null && sprites.length > 0 && sprites[0] != null)
            {
                image = sprites[0].toBufferedImage();
                originals.put(spriteId, image);
            }
        }
        return image;
    }

    public BufferedImage getPadded(Widget widget)
    {
        if (widget == null) return null;
        SpritePixels replacement = client.getWidgetSpriteOverrides().get(widget.getId());
        if (replacement == null) return getSprite(widget.getSpriteId());
        OverrideImage cached = paddedReplacements.get(widget.getId());
        if (cached == null || cached.source != replacement)
        {
            cached = new OverrideImage(replacement, paddedImage(replacement));
            paddedReplacements.put(widget.getId(), cached);
        }
        return cached.image;
    }

    public BufferedImage getSprite(int spriteId)
    {
        if (spriteId < 0) return null;
        int key = ~spriteId;
        SpritePixels replacement = client.getSpriteOverrides().get(spriteId);
        if (replacement != null)
        {
            OverrideImage cached = replacements.get(key);
            if (cached == null || cached.source != replacement)
            {
                cached = new OverrideImage(replacement, paddedImage(replacement));
                replacements.put(key, cached);
            }
            return cached.image;
        }
        replacements.remove(key);
        BufferedImage image = paddedOriginals.get(spriteId);
        if (image == null)
        {
            SpritePixels[] loaded = client.getSprites(client.getIndexSprites(), spriteId, 0);
            if (loaded != null && loaded.length > 0 && loaded[0] != null)
            {
                image = paddedImage(loaded[0]);
                if (image != null) paddedOriginals.put(spriteId, image);
            }
        }
        return image;
    }

    public void clear() { originals.clear(); paddedOriginals.clear(); replacements.clear(); paddedReplacements.clear(); }

    private static BufferedImage paddedImage(SpritePixels sprite)
    {

        int width = sprite.getMaxWidth(), height = sprite.getMaxHeight();
        int x = sprite.getOffsetX(), y = sprite.getOffsetY();
        if (width <= 0 || height <= 0 || width > 512 || height > 512
            || x < 0 || y < 0 || (long) x + sprite.getWidth() > width
            || (long) y + sprite.getHeight() > height) return null;
        BufferedImage crop = sprite.toBufferedImage();
        if (crop == null) return null;
        if (x == 0 && y == 0 && crop.getWidth() == width && crop.getHeight() == height) return crop;
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try { graphics.drawImage(crop, x, y, null); }
        finally { graphics.dispose(); }
        return image;
    }

    private static <T> Map<Integer, T> boundedMap()
    {
        return new LinkedHashMap<Integer, T>(64, 0.75f, true)
        {
            @Override protected boolean removeEldestEntry(Map.Entry<Integer, T> entry)
            { return size() > 64; }
        };
    }

    private static final class OverrideImage
    {
        final SpritePixels source;
        final BufferedImage image;
        OverrideImage(SpritePixels source, BufferedImage image) { this.source = source; this.image = image; }
    }
}

package com.interfacelayout.layout.menu;

import com.interfacelayout.util.WidgetBoundsExpander;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;

@Singleton
public class MenuOverlayBridge
{
    @Inject private OverlayManager overlays;
    @Inject private MenuStoneController menu;
    @Inject private WidgetBoundsExpander expander;
    private final Map<String, GroupOverlay> groups = new HashMap<>();
    private final List<Overlay> nativeOverlays = new ArrayList<>();
    private Runnable refresh = () -> {};
    private boolean running;

    public void start(Runnable refresh) { this.refresh = refresh; running = true; sync(); }
    public void stop()
    {
        running = false;
        groups.values().forEach(overlay -> { overlay.getBounds().setSize(0, 0); overlays.remove(overlay); }); groups.clear();
        nativeOverlays.forEach(overlays::add); nativeOverlays.clear();
    }
    public void sync()
    {
        if (!running) return;

        String prefix = "INTERFACE_LAYOUT_MENU_" + menu.layoutMode() + "_"
            + (menu.individualDragging() ? "group_" : "row_");
        groups.values().removeIf(overlay -> {
            if (!overlay.name.startsWith(prefix) || overlay.name.equals(name(overlay.id))) return false;
            overlay.getBounds().setSize(0, 0); overlays.remove(overlay); return true;
        });

        nativeOverlays.removeIf(overlay -> {
            if (replacesNativeOverlay(overlay.getName())) return false;
            overlays.add(overlay); return true;
        });
        overlays.removeIf(overlay -> {
            if (!replacesNativeOverlay(overlay.getName())) return false;

            overlay.getBounds().setSize(0, 0);
            nativeOverlays.add(overlay); return true;
        });
        menu.groups().forEach((id, bounds) -> {
            String key = name(id);
            if (!groups.containsKey(key))
            {
                GroupOverlay overlay = new GroupOverlay(key, id);
                overlay.getBounds().setBounds(bounds);
                groups.put(key, overlay); overlays.add(overlay);
            }
            GroupOverlay overlay = groups.get(key);
            overlay.getBounds().setSize(bounds.getSize());
            if (overlay.getPreferredLocation() == null && overlay.getPreferredPosition() == null)
                overlay.getBounds().setLocation(bounds.getLocation());
        });
        groups.values().forEach(overlay -> {
            if (!overlay.name.equals(name(overlay.id)) || !menu.groups().containsKey(overlay.id))
                overlay.getBounds().setSize(0, 0);
        });
    }
    private boolean replacesNativeOverlay(String name)
    {

        if (name.equals("RESIZABLE_MINIMAP_STONES_WIDGET"))
            return expander.isExpanded(InterfaceID.ToplevelOsrsStretch.MAP_CONTAINER);
        if (name.equals("RESIZABLE_MINIMAP_WIDGET"))
            return expander.isExpanded(InterfaceID.ToplevelPreEoc.MAP_CONTAINER);
        if (!menu.mode().equals("modern") || menu.groups().isEmpty()) return false;
        int row;
        if (name.equals("RESIZABLE_VIEWPORT_BOTTOM_LINE_TABS1")) row = 1;
        else if (name.equals("RESIZABLE_VIEWPORT_BOTTOM_LINE_TABS2")) row = 0;
        else return false;
        return menu.individualDragging() || menu.groups().containsKey(row);
    }
    private String name(int id)
    {
        return "INTERFACE_LAYOUT_MENU_" + menu.layoutMode() + "_"
            + (menu.individualDragging() ? "group_" : "row_") + id
            + (menu.individualDragging() && menu.groupGeneration(id) > 0 ? "_" + menu.groupGeneration(id) : "");
    }
    public void moveGroupingStone(int id, Point canvas, boolean beginning)
    {
        GroupOverlay overlay = groups.get(name(id));
        if (overlay == null) return;
        if (beginning) clearPreference(id);
        overlay.setPreferredPosition(null);
        overlay.setPreferredLocation(new Point(canvas));
    }
    public void finishGroupingStone(int id)
    {
        GroupOverlay overlay = groups.get(name(id));
        if (overlay != null) overlays.saveOverlay(overlay);
    }
    public void clearPreference(int id)
    {
        GroupOverlay overlay = groups.get(name(id));
        if (overlay != null) { overlays.resetOverlay(overlay); overlay.lastApplied = null; overlay.reset = false; }
    }
    public void resetAll()
    {

        for (String mode : new String[]{"fixed", "classic", "modern", "fixed_overlay", "classic_overlay", "modern_overlay"})
            for (String kind : new String[]{"group_", "row_"})
                for (int id = 0; id <= 14; id++)
                {
                    overlays.resetOverlay(new GroupOverlay("INTERFACE_LAYOUT_MENU_" + mode + "_" + kind + id, id));
                    int version = menu.groupGeneration(mode, id);
                    if (kind.equals("group_") && version > 0)
                        overlays.resetOverlay(new GroupOverlay("INTERFACE_LAYOUT_MENU_" + mode + "_" + kind + id + "_" + version, id));
                }
        groups.values().forEach(overlay -> { overlays.resetOverlay(overlay); overlay.lastApplied = null; });
    }
    public final class GroupOverlay extends Overlay
    {
        private final String name;
        private final int id;
        private Point lastApplied;
        private boolean reset;
        GroupOverlay(String name, int id)
        {
            this.name = name; this.id = id;
            setPosition(OverlayPosition.DYNAMIC);
            setLayer(OverlayLayer.UNDER_WIDGETS);
            setPriority(Overlay.PRIORITY_HIGHEST);
            setMovable(true); setSnappable(true);
        }
        @Override public String getName() { return name; }
        @Override public void revalidate()
        {

            reset = getPreferredLocation() == null && getPreferredPosition() == null && lastApplied != null;
        }
        @Override public Dimension render(Graphics2D graphics)
        {
            Rectangle actual = menu.groups().get(id);
            if (!running || !name.equals(MenuOverlayBridge.this.name(id)) || actual == null) return null;
            if (reset && getPreferredLocation() == null && getPreferredPosition() == null)
            {
                reset = false; lastApplied = null; menu.resetGroup(id); refresh.run();
                actual = menu.groups().get(id);
                if (actual == null) return null;
            }
            reset = false;
            if (getPreferredLocation() != null || getPreferredPosition() != null)
            {

                Point position = getBounds().getLocation();
                if (!position.equals(lastApplied))
                {
                    lastApplied = new Point(position);
                    menu.saveGroup(id, position); refresh.run();
                }
            }
            else getBounds().setLocation(actual.getLocation());
            return actual.getSize();
        }
    }
}

package com.interfacelayout.layout.menu;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class MenuOverlayState
{
    private static final String GROUP = "interfacelayout";
    private static final String ACTIVE = "menuOverlayStateActive";
    private static final String[] OPTIONS = {
        "menuLayout", "menuDirection", "menuSpacing", "menuRestoreLogoutTab",
        "allowClicksThroughGaps", "hideTopMenu", "hideBottomMenu", "hideLeftBar", "hideRightBar", "hiddenStones",
        "hideStone0", "hideStone1", "hideStone2", "hideStone3", "hideStone4", "hideStone5", "hideStone6",
        "hideStone7", "hideStone8", "hideStone9", "hideStone10", "hideStone11", "hideStone12", "hideStone13"
    };
    @Inject private ConfigManager configs;

    public void sync(boolean requested)
    {
        boolean active = Boolean.parseBoolean(configs.getConfiguration(GROUP, ACTIVE));
        if (active == requested) return;
        if (requested)
        {
            save("native");
            if (Boolean.parseBoolean(configs.getConfiguration(GROUP, "menuSnapshot_overlay_ready"))) load("overlay");
            else save("overlay");
        }
        else
        {
            save("overlay");
            if (Boolean.parseBoolean(configs.getConfiguration(GROUP, "menuSnapshot_native_ready"))) load("native");
        }
        configs.setConfiguration(GROUP, ACTIVE, Boolean.toString(requested));
    }

    private void save(String slot)
    {
        for (String key : OPTIONS) copy(key, "menuSnapshot_" + slot + "_" + key);
        configs.setConfiguration(GROUP, "menuSnapshot_" + slot + "_ready", "true");
    }

    private void load(String slot)
    {
        for (String key : OPTIONS) copy("menuSnapshot_" + slot + "_" + key, key);
    }

    public void seedMode(String mode)
    {
        String ready = "menuOverlaySeeded_" + mode;
        if (Boolean.parseBoolean(configs.getConfiguration(GROUP, ready))) return;
        for (String pattern : layoutKeys()) copy(pattern.replace("{mode}", mode), pattern.replace("{mode}", mode + "_overlay"));
        configs.setConfiguration(GROUP, ready, "true");
    }

    private void copy(String source, String destination)
    {
        String value = configs.getConfiguration(GROUP, source);
        if (value == null) configs.unsetConfiguration(GROUP, destination);
        else configs.setConfiguration(GROUP, destination, value);
    }

    private static List<String> layoutKeys()
    {
        List<String> keys = new ArrayList<>();
        keys.add("menuSeparateRows_{mode}"); keys.add("menuBottomGroup_{mode}"); keys.add("menuPosition_{mode}");
        for (int i = 0; i < 2; i++) keys.add("menuNativePosition_{mode}_" + i);
        for (int i = 0; i <= 14; i++)
            for (String prefix : new String[]{"menuGroup_", "menuOrder_", "menuHorizontal_", "menuGroupPosition_", "menuGeneration_"})
                keys.add(prefix + "{mode}_" + i);
        return keys;
    }
}

