import com.interfacelayout.util.WidgetGeometry;
import java.awt.AlphaComposite;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

final class CircularCompassFrame {
    private Widget compass, replacedFrame;
    private Rectangle circle;
    private int originalOpacity, compassOpacity;

    void restore(OrbController manager) {

        if (replacedFrame != null && manager.compassFrame == replacedFrame && replacedFrame.getOpacity() == 255)
            replacedFrame.setOpacity(originalOpacity);
        replacedFrame = null;
        compass = null;
        circle = null;
    }

    void refresh(Client client, OrbController manager) {
        if (manager.isCompassHidden() || manager.isMinimapMinimized()) return;
        int id = manager.isFixedMode() ? InterfaceID.Toplevel.MAPCONTAINER_GRAPHIC5
            : manager.isClassicResizable() ? OrbConstants.Widgets.Classic.COMPASS
            : OrbConstants.Widgets.Modern.COMPASS;
        Widget widget = client.getWidget(id);
        if (widget == null || widget.getContentType() != OrbConstants.Layout.MinimapOverlay.COMPASS_CONTENT
            || widget.isHidden() || widget.getOpacity() == 255) return;
        Rectangle bounds = WidgetGeometry.bounds(widget);
        if (bounds.width <= 0 || bounds.height <= 0) return;
        compass = widget;
        compassOpacity = widget.getOpacity();
        circle = CircularOrbArtwork.around(bounds);
        Widget frame = manager.compassFrame;
        if (frame != null && !frame.isHidden() && frame.getOpacity() < 255) {
            replacedFrame = frame;
            originalOpacity = frame.getOpacity();
            frame.setOpacity(255);
        }
    }

    void paint(Graphics2D g, CircularOrbArtwork artwork) {
        if (compass == null || circle == null || compass.isHidden()) return;
        Graphics2D draw = (Graphics2D) g.create();
        try {
            draw.setComposite(AlphaComposite.SrcOver.derive((255 - compassOpacity) / 255f));
            artwork.paint(draw, circle);
        } finally { draw.dispose(); }
    }
}

package com.interfacelayout.layout.orbs;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;

final class CircularOrbArtwork {
    private final Map<Integer, BufferedImage> frames = new LinkedHashMap<Integer, BufferedImage>(8, .75f, true) {
        @Override protected boolean removeEldestEntry(Map.Entry<Integer, BufferedImage> entry) { return size() > 8; }
    };

    void clear() { frames.clear(); }

    static Rectangle around(Rectangle content) {
        int diameter = Math.max(content.width, content.height) + 8;
        return new Rectangle(content.x + (content.width - diameter) / 2,
            content.y + (content.height - diameter) / 2, diameter, diameter);
    }

    static boolean contains(Rectangle circle, int x, int y) {
        if (circle.width <= 0 || circle.height <= 0) return false;
        double dx = (x + .5 - circle.getCenterX()) / (circle.width / 2.0);
        double dy = (y + .5 - circle.getCenterY()) / (circle.height / 2.0);
        return dx * dx + dy * dy <= 1;
    }

    void paintBackground(Graphics2D graphics, Rectangle circle) {
        Graphics2D draw = (Graphics2D) graphics.create();
        try {
            draw.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            draw.setColor(new Color(14, 20, 24));
            draw.fill(new Ellipse2D.Double(circle.x + 2, circle.y + 2, circle.width - 4, circle.height - 4));
        } finally { draw.dispose(); }
    }

    void paint(Graphics2D g, Rectangle circle) {
        if (circle.width < 10 || circle.width != circle.height) return;
        g.drawImage(frames.computeIfAbsent(circle.width, CircularOrbArtwork::create), circle.x, circle.y, null);
    }

    private static BufferedImage create(int diameter) {

        BufferedImage large = new BufferedImage(diameter * 4, diameter * 4, BufferedImage.TYPE_INT_ARGB);
        Graphics2D draw = large.createGraphics();
        try {
            draw.scale(4, 4);
            draw.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            band(draw, diameter, 0, 4, new Color(18, 23, 27));
            band(draw, diameter, .8, 1.7, new Color(139, 146, 152));
            band(draw, diameter, 1.7, 3, new Color(48, 54, 59));
            band(draw, diameter, 3, 4, new Color(12, 16, 19));
        } finally { draw.dispose(); }
        BufferedImage image = new BufferedImage(diameter, diameter, BufferedImage.TYPE_INT_ARGB);
        draw = image.createGraphics();
        try {
            draw.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
            draw.drawImage(large, 0, 0, diameter, diameter, null);
        } finally { draw.dispose(); }
        return image;
    }

    private static void band(Graphics2D g, int diameter, double outside, double inside, Color color) {
        Area ring = new Area(new Ellipse2D.Double(outside, outside, diameter - outside * 2, diameter - outside * 2));
        ring.subtract(new Area(new Ellipse2D.Double(inside, inside, diameter - inside * 2, diameter - inside * 2)));
        g.setColor(color);
        g.fill(ring);
    }
}

package com.interfacelayout.layout.orbs;

import com.interfacelayout.util.WidgetGeometry;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

final class CircularOrbInput {
    private final Map<Widget, Geometry> geometry = new IdentityHashMap<>();
    private final List<Widget> order = new ArrayList<>();
    private final Map<Widget, Boolean> blocking = new IdentityHashMap<>();

    void apply(Widget parent, Widget backing, Widget button, Widget number, Rectangle circle, boolean hovered) {
        Rectangle active = hovered ? circle : new Rectangle(circle.x + circle.width / 2, circle.y + circle.height / 2, 0, 0);
        List<Widget> children = CircularOrbLayers.children(parent);
        for (Widget widget : new Widget[]{backing, button, number})
            if (widget != null && widget.getParent() == parent && !children.contains(widget)) children.add(widget);
        Map<Widget, Rectangle> positions = new IdentityHashMap<>();
        for (Widget child : children) positions.put(child, WidgetGeometry.bounds(child));
        setBounds(parent, active);
        for (Widget child : children) setBounds(child, positions.get(child));
        clip(backing, active);
        clip(button, active);
        clip(number, active);
        if (parent.getNoClickThrough()) {
            block(parent, false);
            if (backing != null) block(backing, hovered);
        }
        for (Widget child : children) if (child.getNoClickThrough()) {
            clip(child, active);
            if (!hovered) block(child, false);
        }
    }

    private void block(Widget widget, boolean value) {
        if (widget.getNoClickThrough() == value) return;
        blocking.putIfAbsent(widget, widget.getNoClickThrough());
        widget.setNoClickThrough(value);
    }

    private void clip(Widget widget, Rectangle circle) {
        if (widget == null) return;
        Rectangle clipped = WidgetGeometry.bounds(widget).intersection(circle);
        clipped.width = Math.max(0, clipped.width); clipped.height = Math.max(0, clipped.height);
        setBounds(widget, clipped);
    }

    private void setBounds(Widget widget, Rectangle bounds) {
        Rectangle parent = WidgetGeometry.bounds(widget.getParent());
        int x = bounds.x - parent.x + (widget.getParent() == null ? 0 : widget.getParent().getScrollX());
        int y = bounds.y - parent.y + (widget.getParent() == null ? 0 : widget.getParent().getScrollY());
        Geometry state = geometry.get(widget);
        if (state == null) {
            state = new Geometry(widget);
            geometry.put(widget, state); order.add(widget);
        }
        state.apply(widget, x, y, bounds.width, bounds.height);
    }

    void restore(Client client) {
        for (Widget widget : order) if (current(client, widget)) geometry.get(widget).restore(widget);
        blocking.forEach((widget, before) -> {
            if (current(client, widget) && widget.getNoClickThrough() != before) widget.setNoClickThrough(before);
        });
        geometry.clear(); order.clear(); blocking.clear();
    }

    static boolean current(Client client, Widget widget) {
        Widget current = client.getWidget(widget.getId());
        return current == widget || current != null && widget.getIndex() >= 0 && current.getChild(widget.getIndex()) == widget;
    }

    private static final class Geometry {
        final int x, y, width, height, xMode, yMode, widthMode, heightMode;
        int nextX, nextY, nextWidth, nextHeight;
        Geometry(Widget w) {
            x=w.getOriginalX();y=w.getOriginalY();width=w.getOriginalWidth();height=w.getOriginalHeight();
            xMode=w.getXPositionMode();yMode=w.getYPositionMode();widthMode=w.getWidthMode();heightMode=w.getHeightMode();
        }
        void apply(Widget w, int nx, int ny, int nw, int nh) {
            nextX=nx;nextY=ny;nextWidth=nw;nextHeight=nh;
            w.setXPositionMode(0);w.setYPositionMode(0);w.setWidthMode(0);w.setHeightMode(0);
            w.setOriginalX(nx);w.setOriginalY(ny);w.setOriginalWidth(nw);w.setOriginalHeight(nh);w.revalidate();
        }
        void restore(Widget w) {
            if(w.getOriginalX()==nextX && w.getXPositionMode()==0) { w.setOriginalX(x);w.setXPositionMode(xMode); }
            if(w.getOriginalY()==nextY && w.getYPositionMode()==0) { w.setOriginalY(y);w.setYPositionMode(yMode); }
            if(w.getOriginalWidth()==nextWidth && w.getWidthMode()==0) { w.setOriginalWidth(width);w.setWidthMode(widthMode); }
            if(w.getOriginalHeight()==nextHeight && w.getHeightMode()==0) { w.setOriginalHeight(height);w.setHeightMode(heightMode); }
            w.revalidate();
        }
    }
}

package com.interfacelayout.layout.orbs;

import com.interfacelayout.layout.menu.MenuButtonSprites;
import com.interfacelayout.util.WidgetGeometry;
import java.awt.AlphaComposite;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

final class CircularOrbLayers
{
    private final List<Layer> layers = new ArrayList<>();

    static CircularOrbLayers capture(Widget parent, Widget backing, Widget button, Widget icon,
        MenuButtonSprites sprites, Consumer<Widget> hide)
    {
        CircularOrbLayers result = new CircularOrbLayers();
        Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
        result.capture(parent, backing, button, icon, WidgetGeometry.bounds(parent), sprites, hide, visited);
        return result;
    }

    private void capture(Widget widget, Widget backing, Widget button, Widget icon, Rectangle clip,
        MenuButtonSprites sprites, Consumer<Widget> hide, Set<Widget> visited)
    {
        if (widget == null || !visited.add(widget) || widget.isHidden()) return;
        Rectangle bounds = WidgetGeometry.bounds(widget);
        Rectangle visible = clip.intersection(bounds);
        if (visible.isEmpty()) return;
        if (widget != backing && widget != button && widget != icon && widget.getType() == WidgetType.GRAPHIC
            && widget.getOpacity() < 255)
        {
            BufferedImage image = sprites.getPadded(widget);
            if (image != null)
            {
                layers.add(new Layer(image, bounds, visible, widget.getOpacity()));
                hide.accept(widget);
            }
        }
        if (widget.getType() == WidgetType.LAYER)
            for (Widget child : children(widget)) capture(child, backing, button, icon, visible, sprites, hide, visited);
    }

    static List<Widget> children(Widget widget)
    {
        List<Widget> result = new ArrayList<>();
        Set<Widget> added = Collections.newSetFromMap(new IdentityHashMap<>());
        for (Widget[] group : new Widget[][]{widget.getStaticChildren(), widget.getChildren(), widget.getNestedChildren()})
            if (group != null) for (Widget child : group) if (child != null && added.add(child)) result.add(child);
        return result;
    }

    void paint(Graphics2D graphics, Rectangle circle)
    {
        for (Layer layer : layers)
        {
            Graphics2D draw = (Graphics2D) graphics.create();
            try
            {
                draw.clip(new Ellipse2D.Double(circle.x, circle.y, circle.width, circle.height));
                draw.clip(layer.clip);
                draw.setComposite(AlphaComposite.SrcOver.derive((255 - layer.opacity) / 255f));
                draw.drawImage(layer.image, layer.bounds.x, layer.bounds.y, layer.bounds.width, layer.bounds.height, null);
            }
            finally { draw.dispose(); }
        }
    }

    private static final class Layer
    {
        final BufferedImage image;
        final Rectangle bounds, clip;
        final int opacity;
        Layer(BufferedImage image, Rectangle bounds, Rectangle clip, int opacity)
        {
            this.image = image; this.bounds = bounds; this.clip = clip; this.opacity = opacity;
        }
    }
}

