@Slf4j
public class MinimapOverlay extends Overlay
{
	private final Client client;
	private final OrbController manager;

	private final int componentId = Widgets.MinimapOverlay.UNIVERSE;
	private final Rectangle parentBounds = new Rectangle();
	private boolean revalidate;

	@Inject
	private MinimapOverlay(Client client, OrbController manager)
	{
		this.client = client;
		this.manager = manager;
		setPriority(Overlay.PRIORITY_HIGHEST);
		setLayer(OverlayLayer.UNDER_WIDGETS);
		setPosition(OverlayPosition.CANVAS_TOP_RIGHT);
		setMovable(true);
		setSnappable(true);
	}

	@Override
	public String getName()
	{
		return "COMPACT_ORBS_MINIMAP_OVERLAY";
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Widget widget = client.getWidget(componentId);
		final Rectangle parent = getParentBounds(widget);

		if (parent.isEmpty())
		{
			return null;
		}

		if (widget == null)
		{
			return null;
		}

		if (manager.hideMinimapOverlay())
		{
			return null;
		}

		final Rectangle bounds = getBounds();
		if (getPreferredLocation() != null || getPreferredPosition() != null || (getPosition() != OverlayPosition.DYNAMIC && manager.snapCornerRepositioned))
		{

			widget.setForcedPosition(bounds.x - parent.x, bounds.y - parent.y);
		}
		else
		{
			if (revalidate)
			{
				revalidate = false;
				log.debug("Revalidating : {}", getName());
				widget.setForcedPosition(-1, -1);

				widget.revalidate();
			}

			Rectangle widgetBounds = widget.getBounds();
			bounds.setBounds(widgetBounds.x, widgetBounds.y, widgetBounds.width, widgetBounds.height);
		}

		return new Dimension(widget.getWidth(), widget.getHeight());
	}

	private Rectangle getParentBounds(final Widget widget)
	{
		if (widget == null || widget.isHidden())
		{
			parentBounds.setBounds(0, 0, 0, 0);
			return parentBounds;
		}

		final Widget parent = widget.getParent();

		if (parent == null)
		{
			var d = client.getRealDimensions();
			parentBounds.setBounds(0, 0, d.width, d.height);
		}
		else
		{
			parentBounds.setBounds(parent.getBounds());
		}

		return parentBounds;
	}

	@Override
	public Rectangle getParentBounds()
	{
		if (!client.isClientThread())
		{

			return parentBounds;
		}

		final Widget widget = client.getWidget(componentId);
		return getParentBounds(widget);
	}

	@Override
	public void revalidate()
	{

		revalidate = true;
	}
}

package com.interfacelayout.util;

import java.awt.Point;
import java.awt.Rectangle;

public final class LayoutGeometry
{
    private LayoutGeometry() {}
    public static Point clamp(Point point, int width, int height, int canvasWidth, int canvasHeight)
    {
        return new Point(Math.max(0, Math.min(point.x, Math.max(0, canvasWidth - width))),
            Math.max(0, Math.min(point.y, Math.max(0, canvasHeight - height))));
    }
    public static Point snap(Point point, int grid)
    {
        if (grid <= 1) return new Point(point);
        return new Point(Math.round((float) point.x / grid) * grid, Math.round((float) point.y / grid) * grid);
    }
    public static Point relative(Point canvas, Rectangle parent)
    {
        return new Point(canvas.x - parent.x, canvas.y - parent.y);
    }
}

package com.interfacelayout.util;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class LegacyConfigImporter
{
    @Inject private ConfigManager configs;
    public void importOnce()
    {
        if (Boolean.TRUE.equals(configs.getConfiguration("interfacelayout", "legacyImported", Boolean.class))) return;
        copyGroup("compactorbs");
        copyGroup("menustoneshider");
        configs.setConfiguration("interfacelayout", "legacyImported", true);
    }
    private void copyGroup(String group)
    {
        String prefix = group + ".";
        for (String fullKey : configs.getConfigurationKeys(prefix))
        {
            String key = fullKey.substring(prefix.length());
            if (configs.getConfiguration("interfacelayout", key) != null) continue;
            String value = configs.getConfiguration(group, key);
            if (value != null) configs.setConfiguration("interfacelayout", key, value);
        }
    }
}

