    {
        Client client = mock(Client.class);
        when(client.getCanvasWidth()).thenReturn(1000); when(client.getCanvasHeight()).thenReturn(700);
        Widget root = widget(0, 0, 1000, 700), map = widget(790, 0, 210, 207);
