        doAnswer(invocation -> { size[0] = invocation.getArgument(0); return null; }).when(widget).setOriginalWidth(anyInt());
        doAnswer(invocation -> { size[1] = invocation.getArgument(0); return null; }).when(widget).setOriginalHeight(anyInt());
        return widget;
    }
